import test from 'node:test';import assert from 'node:assert/strict';
import { cp,mkdtemp,readFile,writeFile,readdir,rm,lstat,mkdir } from 'node:fs/promises';import { join,resolve } from 'node:path';import { tmpdir } from 'node:os';import { fork } from 'node:child_process';
import { boundedFixture,driveBounded } from './fixtures/reporting-bounded.mjs';import * as api from '../src/automation-reporting-bounded.mjs';import { historyBytes,historyHash } from '../src/automation-reporting-discovery.mjs';
let sequence=0;const fresh=request=>({...request,jobId:'receipt-test-'+String(sequence++).padStart(4,'0'),executionId:'callback'});const ref=(value,current)=>({stateDirectory:value.stateDirectory,captureId:current.captureId,cursor:current.cursor});
async function setup(size=832){const value=await boundedFixture(1,size);const first=await driveBounded(value,{maxJobs:64});value.request={...value.request,generation:2,previous:{captureId:first.current.captureId,cursor:first.current.cursor,reference:first.current.inventory}};let current=await api.beginBoundedHistory(fresh(value.request));while(current.status==='incomplete')current=await api.advanceBoundedHistory(fresh(ref(value,current)));while(true){current=await api.advanceBoundedPublication(fresh(ref(value,current)),{window:1});const cursor=JSON.parse(await readFile(join(value.stateDirectory,current.captureId,'cursors',current.cursor+'.json')));if(cursor.pub?.ancestor===null)break;}return {value,first,current};}
async function launch(request){const info=await lstat(request.stateDirectory,{bigint:true});return {stateDirectory:request.stateDirectory,jobId:request.jobId,executionId:request.executionId,captureId:request.captureId,cursor:request.cursor,actionId:request.actionId,controllerDev:String(info.dev),controllerIno:String(info.ino),...(request.attemptDeadline?{attemptDeadline:request.attemptDeadline}:{}),...(request.recoverReceipt?{recoverReceipt:{open:request.recoverReceipt.open}}:{}),...(request.ownerHeadCheckpoint?{ownerHeadCheckpoint:request.ownerHeadCheckpoint}:{})};}
async function copied(base){const root=join(base,'src');await cp(resolve('src'),root,{recursive:true});const path=join(root,'automation-reporting-bounded.mjs');let source=await readFile(path,'utf8');const link="try{this.reserve(0);await link(pending,path);this.writeOps++;won=true;}";assert.equal(source.split(link).length,2);source=source.replace(link,"try{await globalThis.__ownerTurnGate('before-'+JSON.parse(bytes).decision.kind,path,JSON.parse(bytes));this.reserve(0);await link(pending,path);this.writeOps++;won=true;await globalThis.__ownerTurnGate('after-'+JSON.parse(bytes).decision.kind,path,JSON.parse(bytes));}");
  const body="if(acquireRequest)request=await acquireRequest(job,request);";assert.equal(source.split(body).length,2);source=source.replace(body,"if(acquireRequest){request=await acquireRequest(job,request);await globalThis.__receiptGate('after-body',job);if(globalThis.__expireAfterBody)await new Promise(resolve=>setTimeout(resolve,Math.max(1,job.deadline-Date.now()+20)));}");
  source=source.replace("await job.put(path,bytes);const ref={kind:'terminal-evidence-attempt'", "await globalThis.__receiptGate('before-terminal-marker',job);await job.put(path,bytes);const ref={kind:'terminal-evidence-attempt'");
  source=source.replace("job.receiptAttempt={state:s,open:ref,turn:{decision:marker},terminal:true,poison:head.head};return {state:s};", "job.receiptAttempt={state:s,open:ref,turn:{decision:marker},terminal:true,poison:head.head};await globalThis.__receiptGate('after-terminal-marker',job);return {state:s};");
  source=source.replace("  job.retentionBytes=0;job.retentionOps=0;if(job.inputReceipt)","  await globalThis.__receiptGate('after-core',job,{result});job.retentionBytes=0;job.retentionOps=0;if(job.inputReceipt)");
  source=source.replace("raw=await job.read(request.rawPath,{size:identity.size,inputIdentity:identity});","raw=await job.read(request.rawPath,{size:identity.size,inputIdentity:identity});await globalThis.__receiptGate('after-raw-acquired',job);");
  source=source.replace("  try{job.reserve(input.size+(intent.method==='downloadRaw'?(intent.expected.size??131072):0)+4096);","  await globalThis.__marginPressure(job,input.size+(intent.method==='downloadRaw'?(intent.expected.size??131072):0)+4096);try{job.reserve(input.size+(intent.method==='downloadRaw'?(intent.expected.size??131072):0)+4096);");
  const first="job.retentionBytes=0;job.retentionOps=0;await job.putJSON(join(root,name+'-accepted.json'),evidence);";assert.equal(source.split(first).length,2);source=source.replace(first,"await globalThis.__receiptGate('before-persist',job);"+first+"await globalThis.__receiptGate('after-metadata',job);");
  source=source.replace("await job.put(input.path,job.inputBytes);job.rawCache.set", "await job.put(input.path,job.inputBytes);await globalThis.__receiptGate('after-input',job);job.rawCache.set");source=source.replace("await job.put(rawRef.path,raw);job.rawCache.set", "await job.put(rawRef.path,raw);await globalThis.__receiptGate('after-raw',job);job.rawCache.set");source=source.replaceAll('this.reserve(0);await file.writeFile(bytes);',"this.reserve(0);globalThis.__receiptWrite({phase:path.includes('bounded-owner-turns-')?'owner-turn-start':'payload-start',path,at:Date.now(),bytes:bytes.length});await file.writeFile(bytes);globalThis.__receiptWrite({phase:path.includes('bounded-owner-turns-')?'owner-turn-end':'payload-end',path,at:Date.now(),bytes:bytes.length});");
  source=source.replace('await handle.writeFile(claimBytes);',"globalThis.__receiptWrite({phase:'claim-start',at:Date.now(),bytes:claimBytes.length});await handle.writeFile(claimBytes);globalThis.__receiptWrite({phase:'claim-end',at:Date.now(),bytes:claimBytes.length});");
  source=source.replace('await executionHandle.writeFile(executionBytes);',"globalThis.__receiptWrite({phase:'execution-start',at:Date.now(),bytes:executionBytes.length});await executionHandle.writeFile(executionBytes);globalThis.__receiptWrite({phase:'execution-end',at:Date.now(),bytes:executionBytes.length});");
  source=source.replace("need(Date.now()<=finalizationDeadline,'Terminal finalization window expired');ledger=await open(join(jobs,job.id+'-'+cursor+'.json'),'wx',0o600);","await globalThis.__receiptGate('before-final-ledger',job,{path:join(jobs,job.id+'-'+cursor+'.json'),finalizationDeadline});need(Date.now()<=finalizationDeadline,'Terminal finalization window expired');ledger=await open(join(jobs,job.id+'-'+cursor+'.json'),'wx',0o600);");
  source=source.replaceAll('await link(pending,path);this.writeOps++;',"await link(pending,path);this.writeOps++;globalThis.__receiptWrite({phase:'canonical-link',path,at:Date.now(),kind:path.includes('bounded-owner-turns-')?JSON.parse(bytes).decision.kind:'payload'});");
  source=source.replace('await ledger.writeFile(summary);',"globalThis.__receiptWrite({phase:'terminal-ledger-start',at:Date.now(),bytes:summary.length,deadline:finalizationDeadline});await ledger.writeFile(summary);globalThis.__receiptWrite({phase:'terminal-ledger-end',at:Date.now(),bytes:summary.length,deadline:finalizationDeadline});");
  await writeFile(path,source);return path;
}
async function worker(source,method,request,phase,base){const input=join(base,'worker-'+sequence+++'.json');await writeFile(input,historyBytes(request));const child=fork(resolve('test/fixtures/reporting-bounded-turn-worker.mjs'),[source,method,input,phase],{stdio:['ignore','ignore','pipe','ipc']});const writes=[];const margins=[];let stderr='';child.stderr.on('data',bytes=>{stderr+=bytes;});let readyResolve,resultResolve;const ready=new Promise(resolve=>{readyResolve=resolve;});const result=new Promise(resolve=>{resultResolve=resolve;});child.on('message',message=>{if(message.margin)margins.push(message.margin);if(message.write)writes.push(message.write);if(message.phase)readyResolve(message);if(!message.phase&&(message.result||message.error))resultResolve(message);});const exited=new Promise(resolve=>child.once('exit',(code,signal)=>resolve({code,signal,stderr})));const reached=await Promise.race([ready,exited.then(exit=>{throw Error('Exited before receipt gate '+JSON.stringify(exit));})]);return {child,result,exited,reached,writes,margins};}
async function counter(value){const directory=join(value.stateDirectory,'bounded-owner-turns-'+historyHash(value.request.scope.owners[0].anchor.id));const names=(await readdir(directory)).filter(name=>/^\d{8}\.json$/.test(name)).sort();const cells=[];for(const name of names)cells.push(JSON.parse(await readFile(join(directory,name))));return cells;}
const stop=async worker=>{if(worker&&worker.child.exitCode===null&&worker.child.signalCode===null){worker.child.kill('SIGKILL');await worker.exited;}};

test('180k exact file input is owned before poison and later terminal variants remain distinct',async()=>{
  const {value,first,current}=await setup();try{const request=fresh({...ref(value,first.current),actionId:'00000000',response:{id:'actual-large-contrary',raw:{synthetic:true,padding:'x'.repeat(180000)}}});const file=join(value.base,'actual-input.json');const bytes=Buffer.from(' \n'+JSON.stringify(request)+'\n');await writeFile(file,bytes);const result=await api.runBoundedHistoryFile('respond',file,{launch:await launch(request)});assert.equal(result.status,'blocked',JSON.stringify(result));assert.equal(result.canonicalVariant,'not-generated');assert.equal(result.inputReceipt.format,'raw-file-request');assert.deepEqual(await readFile(result.inputReceipt.path),bytes);assert.equal(result.inputReceipt.sha256,historyHash(bytes));assert.notEqual((await lstat(file)).ino,(await lstat(result.inputReceipt.path)).ino);assert.ok(result.actuals.readBytes>=bytes.length);assert.ok(result.actuals.chargedBytes<=262144);assert.ok(result.actuals.writeBytes>=bytes.length);assert.equal(result.actuals.reservedProviderCalls,0);assert.equal(result.actuals.knownActualProviderCalls,0);const poison=(await counter(value)).at(-1);assert.equal(poison.decision.kind,'poison');await writeFile(file,'{}');const next=await api.advanceBoundedPublication(fresh(ref(value,current)));assert.equal(next.execute,false);assert.equal(next.status,'blocked');
    for(const id of ['second-actual-variant','third-actual-variant']){const variant=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000000',response:{id,raw:{synthetic:true}}}));assert.equal(variant.status,'blocked');assert.equal(variant.inputReceipt.open.kind,'terminal-evidence-attempt');assert.equal(JSON.parse(await readFile(variant.inputReceipt.path)).response.id,id);assert.deepEqual((await counter(value)).at(-1),poison);}
  }finally{await rm(value.base,{recursive:true,force:true});}
});

test('real deadline expiry after actual body acquisition leaves open and fresh exact recovery poisons it',async()=>{
  const {value,first,current}=await setup();let child;try{const source=await copied(value.base);const request=fresh({...ref(value,first.current),actionId:'00000000',attemptDeadline:new Date(Date.now()+3000).toISOString(),response:{id:'actual-expired-contrary',raw:{synthetic:true,padding:'x'.repeat(180000)}}});const file=join(value.base,'expiring-body.json');const bytes=historyBytes(request);await writeFile(file,bytes);child=await worker(source,'runFile',{action:'respond',file,launch:await launch(request)},'after-body',value.base);assert.ok(child.reached.actuals.readBytes>=bytes.length);assert.ok(child.reached.open);await new Promise(resolve=>setTimeout(resolve,Math.max(1,child.reached.deadline-Date.now()+50)));child.child.send('resume');const expired=(await child.result).result;assert.equal((await child.exited).code,0);assert.equal(expired.status,'budget-stop');assert.equal(expired.actuals.deadline,child.reached.deadline);assert.equal(expired.inputReceipt,undefined);assert.ok(child.writes.filter(write=>write.phase==='payload-start'||write.phase==='owner-turn-start').every(write=>write.at<=expired.actuals.deadline));assert.ok(child.writes.some(write=>write.phase==='terminal-ledger-start'&&write.at>expired.actuals.deadline&&write.at<=expired.finalization.deadline));assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');const held=await api.advanceBoundedPublication(fresh(ref(value,current)));assert.equal(held.execute,false);assert.equal(held.status,'receipt-held');
    const recovered=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000000',recoverReceipt:{open:expired.openReceipt,inputPath:file}}));assert.equal(recovered.status,'blocked',JSON.stringify(recovered));assert.deepEqual(await readFile(recovered.inputReceipt.path),bytes);const evidence=JSON.parse(await readFile(join(value.stateDirectory,'bounded-receipt-inputs-'+historyHash(value.request.scope.owners[0].anchor.id),expired.openReceipt.sha256+'-accepted.json')));assert.equal(evidence.originalDeadline,expired.actuals.deadline);assert.ok(evidence.recordedBy.deadline>evidence.originalDeadline);assert.equal((await counter(value)).at(-1).decision.kind,'poison');assert.deepEqual(await readFile(file),bytes);
    await mkdir('.local/consumer-evidence',{recursive:true});await writeFile('.local/consumer-evidence/receipt-expired-after-read.json',JSON.stringify({runtime:process.version,sourceSha256:historyHash(await readFile('src/automation-reporting-bounded.mjs')),instrumentedSha256:historyHash(await readFile(source)),writes:child.writes,expired,recovered:{status:recovered.status,inputReceipt:recovered.inputReceipt,actuals:recovered.actuals}},null,2));
  }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}
});

test('crashes around open input notice and poison retain uncertainty or exact actual evidence',async()=>{
  for(const phase of ['before-receipt-open','after-receipt-open','before-persist','after-metadata','after-input','before-poison','after-poison']){const {value,first,current}=await setup();let child;try{const source=await copied(value.base);const request=fresh({...ref(value,first.current),actionId:'00000000',response:{id:'actual-crash-'+phase,raw:{synthetic:true}}});const file=join(value.base,'caller-held.json');const bytes=historyBytes(request);await writeFile(file,bytes);child=await worker(source,'runFile',{action:'respond',file,launch:await launch(request)},phase,value.base);await stop(child);const cells=await counter(value);const opened=cells.findLast(cell=>cell.decision.kind==='receipt-open');if(phase==='before-receipt-open'){assert.notEqual(cells.at(-1).decision.kind,'receipt-open');continue;}assert.ok(opened);const open={sequence:opened.sequence,sha256:historyHash(historyBytes(opened))};const held=await api.advanceBoundedPublication(fresh(ref(value,current)));assert.equal(held.execute,false);assert.ok(['receipt-held','blocked'].includes(held.status));
      const missing=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000000',recoverReceipt:{open}}));if(['after-metadata','after-input','before-poison','after-poison'].includes(phase)&&phase!=='after-metadata')assert.equal(missing.status,'blocked');else assert.equal(missing.execute,false);
      const recovered=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000000',recoverReceipt:{open,inputPath:file}}));assert.equal(recovered.status,'blocked',phase+' '+JSON.stringify(recovered));assert.deepEqual(await readFile(recovered.inputReceipt.path),bytes);assert.equal((await counter(value)).at(-1).decision.kind,'poison');
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

test('expired terminal finalizer never retries reads payload or owner writes on conflict timeout or crash',async()=>{
  for(const fault of ['EEXIST','window','crash']){const {value,first,current}=await setup();let child;try{const source=await copied(value.base);const request=fresh({...ref(value,first.current),actionId:'00000000',attemptDeadline:new Date(Date.now()+1500).toISOString(),response:{id:'terminal-fault',raw:{synthetic:true,padding:'x'.repeat(180000)}}});const file=join(value.base,'terminal-input.json');await writeFile(file,historyBytes(request));child=await worker(source,'runFileExpire',{action:'respond',file,launch:await launch(request)},'before-final-ledger',value.base);assert.ok(Date.now()>child.reached.deadline);if(fault==='crash'){await stop(child);}else{if(fault==='EEXIST')await writeFile(child.reached.path,'unchanged-conflicting-ledger');else await new Promise(resolve=>setTimeout(resolve,Math.max(1,child.reached.finalizationDeadline-Date.now()+30)));child.child.send('resume');const result=(await child.result).result;assert.equal((await child.exited).code,0);assert.equal(result.status,'finalization-uncertain');assert.equal(result.execute,false);assert.equal(result.actuals.readOps,child.reached.actuals.readOps);assert.equal(result.actuals.readBytes,child.reached.actuals.readBytes);assert.equal(result.finalization.writeAttempted,false);assert.equal(result.finalization.sourceReads,0);assert.ok(result.actuals.chargedBytes<=262144);if(fault==='EEXIST'){assert.equal(result.finalization.errorCode,'EEXIST');assert.equal(await readFile(child.reached.path,'utf8'),'unchanged-conflicting-ledger');}else await assert.rejects(lstat(child.reached.path),{code:'ENOENT'});}
      assert.ok(child.writes.filter(write=>['payload-start','owner-turn-start','canonical-link'].includes(write.phase)).every(write=>write.at<=child.reached.deadline));const held=await api.advanceBoundedPublication(fresh(ref(value,current)));assert.equal(held.status,'receipt-held');assert.equal(held.execute,false);assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

test('a grant completed before expiry is returned only as historical after delayed finalization',async()=>{
  for(const phase of ['after-core','before-final-ledger']){const {value,current}=await setup();let child;try{const source=await copied(value.base);const request=fresh({...ref(value,current),attemptDeadline:new Date(Date.now()+1200).toISOString()});child=await worker(source,'advanceBoundedPublication',request,phase,value.base);assert.ok(child.reached.actuals.reservedProviderCalls===1);await new Promise(resolve=>setTimeout(resolve,Math.max(1,child.reached.deadline-Date.now()+30)));child.child.send('resume');const result=(await child.result).result;assert.equal((await child.exited).code,0);assert.equal(result.execute,false);assert.ok(['budget-stop','finalization-uncertain'].includes(result.status));assert.equal(result.permissionCommit.historical,true);assert.equal(result.permissionCommit.currentEligibility,'not-established');assert.equal(result.actuals.knownActualProviderCalls,0);const names=(await readdir(join(value.stateDirectory,'bounded-jobs'))).filter(name=>name.startsWith(request.jobId+'-')&&name.endsWith('.json'));for(const name of names){const saved=JSON.parse(await readFile(join(value.stateDirectory,'bounded-jobs',name)));assert.equal(saved.execute,false,'Durable ledger is never a fresh permission');assert.equal(saved.status,'incomplete');assert.equal(saved.ledgerRole,'historical-accounting-only');assert.equal(saved.permissionCommit.historical,true);}assert.equal((await counter(value)).at(-1).decision.kind,'grant');}finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

test('raw expiry and missing or changed original raw identity stay held without invented bytes',async()=>{
  for(const fault of ['none','missing-source','changed-caller','wrong-open','deadline-override']){const {value,first,current}=await setup();let child;try{const source=await copied(value.base);const original=JSON.parse(await readFile(join(value.stateDirectory,first.current.captureId,'responses','00000002.json')));const raw=Buffer.from(await readFile(join(value.stateDirectory,first.current.captureId,'response-raw','00000002.json')));raw[0]=91;const rawPath=join(value.base,'actual-original-raw.json');await writeFile(rawPath,raw);const request=fresh({...ref(value,first.current),actionId:'00000002',rawPath,attemptDeadline:new Date(Date.now()+1300).toISOString(),response:{...original.response,acquisition:{mode:'file-reference',reference:'actual-late-raw'}}});const file=join(value.base,'raw-body.json');await writeFile(file,historyBytes(request));child=await worker(source,'runFile',{action:'respond',file,launch:await launch(request)},'after-raw-acquired',value.base);assert.ok(child.reached.actuals.readBytes>=raw.length);assert.equal(child.reached.actuals.retentionReservation.bytes,8192);assert.equal(child.reached.actuals.retentionReservation.operations,256);await new Promise(resolve=>setTimeout(resolve,Math.max(1,child.reached.deadline-Date.now()+20)));child.child.send('resume');const expired=(await child.result).result;assert.equal((await child.exited).code,0);assert.equal(expired.status,'budget-stop');assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');const root=join(value.stateDirectory,'bounded-receipt-inputs-'+historyHash(value.request.scope.owners[0].anchor.id));
      if(fault==='missing-source')await rm(join(root,expired.openReceipt.sha256+'-raw-source.json'));if(fault==='changed-caller')await writeFile(rawPath,Buffer.alloc(raw.length,120));const recover={open:expired.openReceipt,inputPath:file,rawPath};if(fault==='wrong-open')recover.open={...recover.open,sha256:'f'.repeat(64)};if(fault==='deadline-override')recover.originalDeadline=Date.now()+999999;
      const result=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000002',recoverReceipt:recover}));assert.equal(result.execute,false);if(fault==='none'){assert.equal(result.status,'blocked');assert.deepEqual(await readFile(result.inputReceipt.raw.path),raw);assert.equal((await counter(value)).at(-1).decision.kind,'poison');}else{assert.equal(result.status,'blocked');assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');assert.equal((await api.advanceBoundedPublication(fresh(ref(value,current)))).execute,false);}
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

test('missing owned raw is an explicit gap and corrupt owned raw is never replaced from caller path',async()=>{
  for(const fault of ['missing','corrupt']){const {value,first,current}=await setup();let child;try{const source=await copied(value.base);const old=JSON.parse(await readFile(join(value.stateDirectory,first.current.captureId,'responses','00000002.json')));const raw=Buffer.from(await readFile(join(value.stateDirectory,first.current.captureId,'response-raw','00000002.json')));raw[0]=91;const rawPath=join(value.base,'held-actual-raw.json');await writeFile(rawPath,raw);const request=fresh({...ref(value,first.current),actionId:'00000002',rawPath,response:{...old.response,acquisition:{mode:'file-reference',reference:'owned-raw-check'}}});const file=join(value.base,'owned-body.json');await writeFile(file,historyBytes(request));child=await worker(source,'runFile',{action:'respond',file,launch:await launch(request)},'after-raw',value.base);await stop(child);const open=child.reached.open;const root=join(value.stateDirectory,'bounded-receipt-inputs-'+historyHash(value.request.scope.owners[0].anchor.id));const accepted=JSON.parse(await readFile(join(root,open.sha256+'-accepted.json')));assert.deepEqual(await readFile(accepted.raw.path),raw);if(fault==='missing')await rm(accepted.raw.path);else await writeFile(accepted.raw.path,Buffer.alloc(raw.length,120));
      const gap=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000002',recoverReceipt:{open}}));assert.equal(gap.status,'blocked');assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');
      const explicit=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000002',recoverReceipt:{open,rawPath}}));if(fault==='missing'){assert.equal(explicit.status,'blocked');assert.deepEqual(await readFile(explicit.inputReceipt.raw.path),raw);assert.equal((await counter(value)).at(-1).decision.kind,'poison');}else{assert.equal(explicit.status,'blocked');assert.equal(explicit.inputReceipt,undefined);assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');assert.deepEqual(await readFile(accepted.raw.path),Buffer.alloc(raw.length,120));}
      assert.equal((await api.advanceBoundedPublication(fresh(ref(value,current)))).execute,false);
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

test('one byte below and exactly at reserved acquisition allowance use real charged pressure bytes',async()=>{
  for(const mode of ['Below','At']){const {value,first,current}=await setup();let child;try{const source=await copied(value.base);const request=fresh({...ref(value,first.current),actionId:'00000000',response:{id:'exact-margin-contrary',raw:{synthetic:true}}});const file=join(value.base,'margin-body.json');const bytes=historyBytes(request);await writeFile(file,bytes);const before=await counter(value);child=await worker(source,'runFileMargin'+mode,{action:'respond',file,launch:await launch(request)},'after-core',value.base);assert.equal(child.margins.length,1);const measured=child.margins[0];assert.equal(measured.after.readBytes-measured.before.readBytes,measured.size);assert.equal(measured.after.chargedBytes-measured.before.chargedBytes,measured.size);assert.equal(measured.expectedTotal,262144+(mode==='Below'?1:0));assert.equal(measured.after.retentionReservation.bytes,8192);assert.equal(measured.after.retentionReservation.operations,256);child.child.send('resume');const result=(await child.result).result;assert.equal((await child.exited).code,0);assert.ok(result.actuals.chargedBytes<=262144,JSON.stringify(result));assert.equal(result.actuals.reservedProviderCalls,0);assert.equal(result.actuals.knownActualProviderCalls,0);assert.equal(result.actuals.uncertainProviderCalls,0);
      if(mode==='Below'){assert.ok(['budget-stop','incomplete'].includes(result.status),JSON.stringify(result));if(result.status==='incomplete'){assert.ok(result.ownerHeadCheckpoint?.receipt);assert.match(result.reason,/body remains unread/);}assert.equal(result.openReceipt,undefined);assert.equal(result.inputReceipt,undefined);assert.deepEqual(await counter(value),before);assert.equal(child.writes.some(write=>write.path===file),false);}else{assert.ok(result.openReceipt);assert.ok(result.inputReceipt,JSON.stringify(result));assert.deepEqual(await readFile(result.inputReceipt.path),bytes);assert.equal((await api.advanceBoundedPublication(fresh(ref(value,current)))).execute,false);}
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

test('late successful non-grant result is historical and partial finalizer bytes stay uncertain',async()=>{
  for(const mode of ['late','partial','large-output']){const {value,first}=await setup();let child;try{let source=await copied(value.base);if(mode==='partial'){let text=await readFile(source,'utf8');text=text.replace('await ledger.writeFile(summary);',"await ledger.write(summary,0,17,0);throw Object.assign(Error('actual partial terminal write'),{code:'EIO'});");await writeFile(source,text);}if(mode==='large-output'){let text=await readFile(source,'utf8');text=text.replace("  await globalThis.__receiptGate('after-core',job,{result});", "  result={...result,largeOutput:'x'.repeat(10000)};await globalThis.__receiptGate('after-core',job,{result});");await writeFile(source,text);}const old=JSON.parse(await readFile(join(value.stateDirectory,first.current.captureId,'responses','00000000.json')));const request=fresh({...ref(value,first.current),actionId:'00000000',attemptDeadline:new Date(Date.now()+2000).toISOString(),response:old.response});child=await worker(source,'respondBoundedPublication',request,'after-core',value.base);assert.equal(child.reached.result.execute,false);if(mode==='late')await new Promise(resolve=>setTimeout(resolve,Math.max(1,child.reached.deadline-Date.now()+30)));child.child.send('resume');const result=(await child.result).result;assert.equal((await child.exited).code,0);assert.equal(result.execute,false);assert.ok(result.actuals.chargedBytes<=262144);if(mode==='late'){assert.equal(result.status,'budget-stop');assert.equal(result.historicalStatus,child.reached.result.status);assert.ok(!['retained','published','prepared'].includes(result.status));}else if(mode==='partial'){assert.equal(result.status,'finalization-uncertain');assert.equal(result.finalization.errorCode,'EIO');assert.equal(result.finalization.writeAttempted,true);assert.equal(result.finalization.writeCompleted,false);assert.ok(result.finalization.uncertainBytes>17);assert.ok(result.actuals.categories.summaryRepresentation>=result.finalization.uncertainBytes);assert.equal(result.actuals.writeBytes,child.reached.actuals.writeBytes);assert.equal(result.actuals.readBytes,child.reached.actuals.readBytes);}else{assert.equal(result.status,'finalization-refused');assert.equal(result.largeOutput,undefined);assert.ok(result.jobLedger);}
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

test('changed malformed oversized or missing file after open cannot close or bypass its held attempt',async()=>{
  for(const fault of ['changed','malformed','oversized','missing']){const {value,first,current}=await setup();let child;try{const source=await copied(value.base);const request=fresh({...ref(value,first.current),actionId:'00000000',response:{id:'unacquired-'+fault,raw:{synthetic:true}}});const file=join(value.base,'changed-after-open.json');await writeFile(file,historyBytes(request));child=await worker(source,'runFile',{action:'respond',file,launch:await launch(request)},'after-receipt-open',value.base);const before=child.reached.turn;assert.equal(before.decision.kind,'receipt-open');if(fault==='missing')await rm(file);else if(fault==='oversized')await writeFile(file,Buffer.alloc(300000,120));else if(fault==='malformed')await writeFile(file,'{');else await writeFile(file,historyBytes({...request,response:{id:'changed'}}));child.child.send('resume');const result=(await child.result).result;assert.equal((await child.exited).code,0);assert.equal(result.execute,false);assert.equal(result.inputReceipt,undefined);assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');assert.equal((await api.advanceBoundedPublication(fresh(ref(value,current)))).status,'receipt-held');const recovery=await api.respondBoundedPublication(fresh({...ref(value,first.current),actionId:'00000000',recoverReceipt:{open:result.openReceipt,inputPath:file}}));assert.equal(recovery.execute,false);assert.equal(recovery.inputReceipt,undefined);assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}
});

async function privateAPI(base,mutate=source=>source){const root=join(base,'private-api-'+sequence++);await cp(resolve('src'),root,{recursive:true});const path=join(root,'automation-reporting-bounded.mjs');const original=await readFile(path,'utf8');const source=mutate(original);assert.notEqual(source.length,0);await writeFile(path,source);const api=await import((await import('node:url')).pathToFileURL(path));return {...api,privateSourceSha256:historyHash(Buffer.from(source))};}
function omitFunction(source,name,next){const start=source.indexOf('async function '+name+'(');const end=source.indexOf('async function '+next+'(',start);assert.ok(start>=0&&end>start);return source.slice(0,start)+'async function '+name+'() {}\n'+source.slice(end);}
async function fakeResolution(value,open,kind){const cells=await counter(value);const previous=cells.at(-1);const original=cells.find(cell=>cell.decision.kind==='receipt-resolved');const forged=structuredClone(original);forged.sequence=previous.sequence+1;forged.previous=open;forged.lastGrant=previous.lastGrant;if(kind==='input-hash'){const old=JSON.parse(await readFile(original.decision.evidence.path));const root=join(value.stateDirectory,'bounded-receipt-inputs-'+historyHash(value.request.scope.owners[0].anchor.id));const path=join(root,open.sha256+'-input.json');await writeFile(path,await readFile(old.input.path));const evidence={...old,open,input:{...old.input,path},sourceInput:previous.decision.input,originalDeadline:previous.decision.deadline};const bytes=historyBytes(evidence);const evidencePath=join(root,open.sha256+'-accepted.json');await writeFile(evidencePath,bytes);forged.decision={...forged.decision,open,evidence:{path:evidencePath,size:bytes.length,sha256:historyHash(bytes)}};}const directory=join(value.stateDirectory,'bounded-owner-turns-'+historyHash(value.request.scope.owners[0].anchor.id));await writeFile(join(directory,String(forged.sequence).padStart(8,'0')+'.json'),historyBytes(forged));}

test('paired actual-source controls distinguish open gate exact resolution and last-grant order',async()=>{
  const evidence=[];for(const guard of ['open','wrong-open','input-hash','last-grant'])for(const mode of ['baseline','mutant','restored']){const {value,first,current}=await setup();let child;let targetInput;try{const source=await copied(value.base);if(guard!=='last-grant'){const old=JSON.parse(await readFile(join(value.stateDirectory,first.current.captureId,'responses','00000000.json')));const request=fresh({...ref(value,first.current),actionId:'00000000',response:old.response});child=await worker(source,'respondBoundedPublication',request,'after-receipt-open',value.base);const open={sequence:child.reached.turn.sequence,sha256:historyHash(historyBytes(child.reached.turn))};targetInput=child.reached.turn.decision.input.sha256;await stop(child);if(guard!=='open')await fakeResolution(value,open,guard);}else{const cells=await counter(value);const last=cells.at(-1);assert.equal(last.decision.kind,'receipt-resolved');const grant=cells.findLast(cell=>cell.decision.kind==='grant');const forged={...grant,sequence:last.sequence+1,previous:{sequence:last.sequence,sha256:historyHash(historyBytes(last))},lastGrant:{sequence:grant.sequence,sha256:historyHash(historyBytes(grant))}};const root=join(value.stateDirectory,'bounded-owner-turns-'+historyHash(value.request.scope.owners[0].anchor.id));await writeFile(join(root,String(forged.sequence).padStart(8,'0')+'.json'),historyBytes(forged));}
      const mutated=await privateAPI(value.base,text=>{if(mode!=='mutant')return text;if(guard==='open'){const needle="const isReceiptOpen=turn=>turn?.decision.kind==='receipt-open';";assert.ok(text.includes(needle));assert.ok(targetInput);return text.replace(needle,"const isReceiptOpen=turn=>turn?.decision.kind==='receipt-open'&&turn.decision.input.sha256!=='"+targetInput+"';");}if(guard==='last-grant'){const start=text.indexOf('function validateGrantOrder(');const end=text.indexOf('async function headCheckpoint(',start);assert.ok(start>=0&&end>start);return text.slice(0,start)+'function validateGrantOrder() {}\n'+text.slice(end);}return omitFunction(text,'validateReceiptResolution','checkpointHead');});const result=await mutated.advanceBoundedPublication(fresh(ref(value,current)));assert.equal(result.execute,mode==='mutant',guard+' '+mode+' '+JSON.stringify(result));assert.equal(result.status,mode==='mutant'?'action-required':guard==='open'?'receipt-held':'blocked');evidence.push({guard,mode,status:result.status,execute:result.execute,reason:result.reason??null});
    }finally{await stop(child);await rm(value.base,{recursive:true,force:true});}}await mkdir('.local/consumer-evidence',{recursive:true});await writeFile('.local/consumer-evidence/receipt-actual-source-controls.json',JSON.stringify(evidence,null,2));
});

