test('actual mid-read body raw and path replacement drift leave open with charged actual bytes',async()=>{
  for(const mode of ['body','raw','replacement']){const {value,first,current}=await setup();let changed=false;try{const old=JSON.parse(await readFile(join(value.stateDirectory,first.current.captureId,'responses',mode==='raw'?'00000002.json':'00000000.json')));const rawPath=join(value.base,'mutable-raw.json');const raw=mode==='raw'?await readFile(join(value.stateDirectory,first.current.captureId,'response-raw','00000002.json')):null;if(raw)await writeFile(rawPath,raw);const request=fresh({...ref(value,first.current),actionId:mode==='raw'?'00000002':'00000000',...(raw?{rawPath}:{}),response:raw?{...old.response,acquisition:{mode:'file-reference',reference:'mutable-actual-raw'}}:{...old.response,raw:{synthetic:true,padding:'A'.repeat(16000)}}});const file=join(value.base,'mutable-body.json');const bytes=historyBytes(request);await writeFile(file,bytes);const target=mode==='raw'?rawPath:file;globalThis.__readDrift=async(path,offset)=>{if(path!==target||changed)return;changed=true;const original=await readFile(target);if(mode==='replacement'){await rm(target);await writeFile(target,original);}else if(mode==='raw'){const next=Buffer.from(original);next[Math.floor(next.length/2)]^=1;await writeFile(target,next);}else await writeFile(target,original.toString().replace('A'.repeat(16000),'B'.repeat(16000)));};const instrumented=await privateAPI(value.base,text=>{const needle='const part=await file.read(bytes,offset,bytes.length-offset,null);';assert.ok(text.includes(needle));return text.replace(needle,`const part=await file.read(bytes,offset,Math.min(bytes.length-offset,${mode==='raw'?64:4096}),null);await globalThis.__readDrift(path,offset);`);});const result=await instrumented.runBoundedHistoryFile('respond',file,{launch:await launch(request)});assert.equal(changed,true);assert.equal(result.execute,false);assert.equal(result.inputReceipt,undefined);assert.match(result.reason,/identity changed during read/);assert.ok(result.actuals.readBytes>=bytes.length+(raw?.length??0));assert.equal((await counter(value)).at(-1).decision.kind,'receipt-open');assert.equal((await api.advanceBoundedPublication(fresh(ref(value,current)))).status,'receipt-held');
    }finally{delete globalThis.__readDrift;await rm(value.base,{recursive:true,force:true});}}
});

